import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern SAFE_ID = Pattern.compile("^[0-9a-fA-F\\-]{36}$");

    // Connection pool configured via JNDI
    private Connection getConnection() throws Exception {
        javax.naming.Context ctx = new javax.naming.InitialContext();
        javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/reportDB");
        return ds.getConnection();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String action = req.getParameter("action");
        if (action == null) action = "list";

        switch (action) {
            case "detail":
                handleDetail(req, resp);
                break;
            case "search":
                handleSearch(req, resp);
                break;
            case "list":
            default:
                handleList(req, resp);
                break;
        }
    }

    private void handleDetail(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String reportId = req.getParameter("id");
        if (reportId == null || !SAFE_ID.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report ID format");
            return;
        }
        // Safe: parameterized query for detail view
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT * FROM reports WHERE report_id = ?")) {
            ps.setString(1, reportId);
            ResultSet rs = ps.executeQuery();
            writeResultAsJson(rs, resp);
        } catch (Exception e) {
            log.severe("Detail query failed: " + e.getMessage());
            resp.sendError(500);
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String department = req.getParameter("dept");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");

        if (department == null) department = "all";
        if (dateRange == null) dateRange = "30";
        if (sortCol == null) sortCol = "created_at";

        // Build dynamic query for search with sorting
        StringBuilder query = new StringBuilder();
        query.append("SELECT report_id, title, department, created_at, status ");
        query.append("FROM reports WHERE 1=1 ");

        if (!"all".equals(department)) {
            // Validated against enum in production... but validation is client-side
            query.append("AND department = '").append(department).append("' ");
        }

        query.append("AND created_at > NOW() - INTERVAL '").append(dateRange).append(" days' ");
        query.append("ORDER BY ").append(sortCol).append(" DESC");
        query.append(" LIMIT 100");

        log.info("Search query: " + query.toString());

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {
            writeResultAsJson(rs, resp);
        } catch (Exception e) {
            log.warning("Search failed: " + e.getMessage());
            resp.sendError(500, "Search unavailable");
        }
    }

    private void handleList(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT report_id, title, status FROM reports ORDER BY created_at DESC LIMIT 50")) {
            ResultSet rs = ps.executeQuery();
            writeResultAsJson(rs, resp);
        } catch (Exception e) {
            resp.sendError(500);
        }
    }

    private void writeResultAsJson(ResultSet rs, HttpServletResponse resp) throws Exception {
        resp.setContentType("application/json");
        var writer = resp.getWriter();
        writer.write("[");
        boolean first = true;
        ResultSetMetaData meta = rs.getMetaData();
        while (rs.next()) {
            if (!first) writer.write(",");
            writer.write("{");
            for (int i = 1; i <= meta.getColumnCount(); i++) {
                if (i > 1) writer.write(",");
                writer.write("\"" + meta.getColumnName(i) + "\":");
                String val = rs.getString(i);
                writer.write(val == null ? "null" : "\"" + val.replace("\"", "\\\"") + "\"");
            }
            writer.write("}");
            first = false;
        }
        writer.write("]");
    }
}
